axiom DBraneCharge (p : ℕ) (alpha' : ℝ) :
  let μ_p := 1 / (2 * Real.pi)^p * alpha'^(-(p+1)/2)
  μ_p > 0

axiom ClosedStringMass (ws : Worldsheet) (N Ñ : ℕ) :
  let M2 := (4 / ws.alpha') * (N + Ñ - 2)
  ws.D = 26 → M2 ≥ -4 / ws.alpha'

axiom OpenStringMass (ws : Worldsheet) (N : ℕ) :
  let M2 := (1 / ws.alpha') * (N - 1)
  ws.D = 26 → M2 ≥ -1 / ws.alpha'

axiom finiteSizeScaling
    {Q : ℝ → ℝ} {f_Q : FSScalingFunction}
    {t L : ℝ} {ν Δ_Q : ℝ}
    (hL : L > 0) (hnu : ν > 0) :
    Q t = L ^ (Δ_Q / ν) * f_Q (t * L ^ (1 / ν))
